let palette = ['#EE7485', '#FCB500', '#007EB6', '#232524', '#009135', '#E94015', '#FFF4D3'];
let gridBase = [];
let gridRes = 9;
let cellSize;
let ctx;
let slider;
let tiles = [];
let interval = 20;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	cellSize = width / gridRes;
	for (let i = 0; i < gridRes; i++) {
		gridBase[i] = [];
		for (let j = 0; j < gridRes; j++) {
			let x = i * cellSize + (cellSize / 2);
			let y = j * cellSize + (cellSize / 2);
			gridBase[i][j] = createVector(x, y, cellSize);
			tiles.push(new Tile(x, y, cellSize, j, i));
		}
	}

	slider = new TileSlider();

}

function draw() {

	background('#fff');

	for (let i of tiles) {
		i.run();
	}

	slider.move();

	if (frameCount % interval === 0) {
		slider = new TileSlider();
	}
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function drawChecker(centerX, centerY, totalSize, divisionCount, bgColor, patternColor) {
	let cellSize = totalSize / divisionCount;
	let topLeftX = centerX - totalSize / 2;
	let topLeftY = centerY - totalSize / 2;

	push();
	translate(topLeftX, topLeftY);

	fill(bgColor);
	square(totalSize / 2, totalSize / 2, totalSize);

	for (let row = 0; row < divisionCount; row++) {
		for (let col = 0; col < divisionCount; col++) {
			if ((row + col) % 2 === 0) {
				let posX = col * cellSize;
				let posY = row * cellSize;

				fill(patternColor);
				square(posX + cellSize / 2, posY + cellSize / 2, cellSize);
			}
		}
	}
	pop();
}

function drawPolkaDot(centerX, centerY, totalSize, divisionCount, bgColor, patternColor) {
	let cellSize = totalSize / divisionCount;
	let topLeftX = centerX - totalSize / 2;
	let topLeftY = centerY - totalSize / 2;

	push();
	translate(topLeftX, topLeftY);

	fill(bgColor);
	square(totalSize / 2, totalSize / 2, totalSize);

	for (let row = 0; row < divisionCount; row++) {
		for (let col = 0; col < divisionCount; col++) {
			let posX = col * cellSize;
			let posY = row * cellSize;
			fill(patternColor);
			circle(posX + cellSize / 2, posY + cellSize / 2, cellSize * 0.5);
		}
	}
	pop();
}

function drawStripes(centerX, centerY, totalSize, stripeCount, bgColor, stripeColor) {
	let stripeSpacing = (totalSize * sqrt(2)) / stripeCount;
	let thickness = stripeSpacing * 0.5;

	push();
	translate(centerX - totalSize / 2, centerY - totalSize / 2);
	noStroke();

	fill(bgColor);
	square(totalSize / 2, totalSize / 2, totalSize);

	ctx.clip();

	stroke(stripeColor);
	strokeWeight(thickness);
	strokeCap(PROJECT);

	for (let i = 0; i < stripeCount; i++) {
		let offset = map(i, 0, stripeCount, 0, totalSize * 2) + (totalSize / stripeCount) / 2;
		line(offset, 0, offset - totalSize, totalSize);
	}
	pop();
}

