class Tile {
	constructor(x, y, size, row, col) {
		this.x = x;
		this.y = y;
		this.size = size;
		this.row = row;
		this.col = col;
		this.color1 = random(palette);
		this.color2 = random(palette);
		while (this.color1 == this.color2) {
			this.color2 = random(palette);
		}

		this.isOver = false;

		this.dotsCount = int(random(1, 4));
		this.checkeredCount = int(random(2, 4));
		this.stripeCount = int(random(1, 6));

		this.drawType = int(random(3));

		this.angle = int(random(4)) * (TAU / 4);
	}

	display() {
		push();
		translate(this.x, this.y);
		rotate(this.angle);
		noStroke();
		fill(this.color1);
		if (this.drawType == 0) {
			drawChecker(0, 0, this.size, this.checkeredCount, this.color1, this.color2);
		} else if (this.drawType == 1) {
			drawPolkaDot(0, 0, this.size, this.dotsCount, this.color1, this.color2);
		} else if (this.drawType == 2) {
			drawStripes(0, 0, this.size, this.stripeCount, this.color1, this.color2);
		}
		pop();
	}

	update() { }

	run() {
		this.display();
		this.update();
	}
}

class TileSlider {
	constructor() {
		this.isVertical = random([true, false]);
		this.direction = random([-1, 1]);
		this.selectedIndex = floor(random(gridRes));
		this.timer = 0;
		this.duration = interval;

		if (this.isVertical) {
			let x = gridBase[this.selectedIndex][0].x;
			let col = this.selectedIndex;
			let size = cellSize;

			if (this.direction === 1) {
				let y = gridBase[0][0].y - cellSize;
				tiles.push(new Tile(x, y, size, -1, col));
			} else {
				let y = gridBase[0][gridRes - 1].y + cellSize;
				tiles.push(new Tile(x, y, size, gridRes, col));
			}
		} else {
			let y = gridBase[0][this.selectedIndex].y;
			let row = this.selectedIndex;
			let size = cellSize;

			if (this.direction === 1) {
				let x = gridBase[0][0].x - cellSize;
				tiles.push(new Tile(x, y, size, row, -1));
			} else {
				let x = gridBase[gridRes - 1][0].x + cellSize;
				tiles.push(new Tile(x, y, size, row, gridRes));
			}
		}

		this.startPositions = [];
		this.endPositions = [];

		for (let i = 0; i < tiles.length; i++) {
			let tile = tiles[i];
			if (this.isVertical) {
				this.startPositions.push(tile.y);
				this.endPositions.push(tile.y + tile.size * this.direction);
				if (this.selectedIndex === tile.col) {
					tile.row += this.direction;
				}
			} else {
				this.startPositions.push(tile.x);
				this.endPositions.push(tile.x + tile.size * this.direction);
				if (this.selectedIndex === tile.row) {
					tile.col += this.direction;
				}
			}
		}
	}

	move() {
		this.timer++;

		if (this.timer > 0 && this.timer < this.duration) {
			let progress = norm(this.timer, 0, this.duration - 1);
			let easedProgress = easeInOutCubic(progress);

			for (let i = 0; i < tiles.length; i++) {
				let tile = tiles[i];
				if (this.isVertical) {
					if (this.selectedIndex === tile.col) {
						tile.y = lerp(this.startPositions[i], this.endPositions[i], easedProgress);
					}
				} else {
					if (this.selectedIndex === tile.row) {
						tile.x = lerp(this.startPositions[i], this.endPositions[i], easedProgress);
					}
				}
			}
		}

		if (this.duration <= this.timer) {
			for (let i = tiles.length - 1; i >= 0; i--) {
				let tile = tiles[i];
				if ((tile.x < 0) || (width < tile.x) || (tile.y < 0) || (height < tile.y)) {
					tiles.splice(i, 1);
				}
			}
		}
	}
}

